{
  "title": "French Onion Soup",
  "servings": "3–6 persons",
  "prep_time": "10 minutes",
  "cook_time": "35 minutes",
  "ingredients": [
    {
      "quantity": "3",
      "unit": "cups",
      "name": "onion",
      "prep": "chopped",
      "raw_text": "3 rounded cups (500g) chopped onion"
    },
    {
      "quantity": "2",
      "unit": "tbsp",
      "name": "butter",
      "prep": null,
      "raw_text": "A knob of butter (a little less than 2 tbsp or 25g)"
    },
    {
      "quantity": "1",
      "unit": "tbsp",
      "name": "flour",
      "prep": null,
      "raw_text": "1 tbsp (15g) flour"
    },
    {
      "quantity": "1.5",
      "unit": "liters",
      "name": "beef stock",
      "prep": null,
      "raw_text": "1.5 liters (roughly 5¼ cups) beef stock (chicken or vegetable stock is an acceptable alternative)"
    },
    {
      "quantity": "1",
      "unit": null,
      "name": "bouquet garni",
      "prep": "fresh bay, thyme, and Herbes de Provence, tied in a bundle or in a temporary sack made of cheesecloth",
      "raw_text": "1 bouquet garni (fresh bay, thyme, and Herbes de Provence, tied in a bundle or in a temporary sack made of cheesecloth)"
    },
    {
      "quantity": "1",
      "unit": "slice",
      "name": "stale french bread",
      "prep": "per person, or fresh bread toasted beforehand",
      "raw_text": "1 slice of stale french bread, per person (or fresh bread, toasted beforehand)"
    },
    {
      "quantity": "3",
      "unit": "tbsp",
      "name": "red port wine",
      "prep": null,
      "raw_text": "3 tbsp red (50ml) port wine"
    },
    {
      "quantity": "1",
      "unit": "cup",
      "name": "Gruyère cheese",
      "prep": "grated",
      "raw_text": "1 cup grated (125g) Gruyère cheese"
    },
    {
      "quantity": null,
      "unit": null,
      "name": "nutmeg",
      "prep": null,
      "raw_text": "Nutmeg"
    },
    {
      "quantity": null,
      "unit": null,
      "name": "salt",
      "prep": null,
      "raw_text": "Salt"
    },
    {
      "quantity": null,
      "unit": null,
      "name": "pepper",
      "prep": null,
      "raw_text": "Pepper"
    }
  ],
  "steps": [
    {
      "position": 1,
      "instruction": "Melt the butter in a large saucepan. Stir in the onions, and let the onions blonde on moderate heat (which is to say, let them cook until they are light gold and transparent, but do not let them over-caramelize and become dark).",
      "ingredient_positions": [1, 2]
    },
    {
      "position": 2,
      "instruction": "Add the flour to the onions. Stir gently for 3–4 minutes. The flour will seem to have disappeared, but has been absorbed into the butter. This will give the soup its characteristic slight thickness. Scrape up any of the dark brown butter and flour mixture that has stuck to the bottom of the saucepan; it is called fond, and will add flavour to the soup.",
      "ingredient_positions": [3]
    },
    {
      "position": 3,
      "instruction": "Pour ⅔ of the beef broth over the onions and mix well. Add the bouquet garni. Bring to a boil, stirring regularly.",
      "ingredient_positions": [4, 5]
    },
    {
      "position": 4,
      "instruction": "Season with salt and pepper and a little nutmeg, to taste. Add the rest of the broth, and let the soup simmer gently for 10–15 minutes.",
      "ingredient_positions": [4, 9, 10, 11]
    },
    {
      "position": 5,
      "instruction": "If your bread is fresh, then toast it now over low heat.",
      "ingredient_positions": [6]
    },
    {
      "position": 6,
      "instruction": "Remove the soup from the heat, and remove the bouquet garni. Add port and stir well.",
      "ingredient_positions": [7]
    },
    {
      "position": 7,
      "instruction": "Divide the soup into 6 oven-safe ceramic or glass bowls. Press a slice of bread into the top of each bowl of soup. Generously sprinkle grated Gruyère cheese on top.",
      "ingredient_positions": [6, 8]
    },
    {
      "position": 8,
      "instruction": "Broil on low for 10 minutes, or until the cheese is melted and browned.",
      "ingredient_positions": []
    },
    {
      "position": 9,
      "instruction": "Serve piping hot.",
      "ingredient_positions": []
    }
  ],
  "confidence": 0.92
}

